package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"reflect"
	"strings"
	"sync"
	"testing"

	"bookmarksapi"
)

func do(t *testing.T, ts *httptest.Server, method, path, body string) (int, string) {
	t.Helper()
	var rd io.Reader
	if body != "" {
		rd = strings.NewReader(body)
	}
	req, _ := http.NewRequest(method, ts.URL+path, rd)
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	return resp.StatusCode, string(b)
}

func TestEndpoints(t *testing.T) {
	srv := bookmarksapi.NewServer()
	ts := httptest.NewServer(srv)
	defer ts.Close()

	// invalid JSON
	if c, b := do(t, ts, "POST", "/bookmarks", "{not json"); c != 400 || !strings.Contains(b, `"error"`) {
		t.Fatalf("invalid json: %d %s", c, b)
	}
	// missing url
	if c, _ := do(t, ts, "POST", "/bookmarks", `{"title":"x"}`); c != 400 {
		t.Fatalf("missing url: %d", c)
	}
	// empty url
	if c, _ := do(t, ts, "POST", "/bookmarks", `{"url":""}`); c != 400 {
		t.Fatalf("empty url: %d", c)
	}
	// bad tags
	if c, _ := do(t, ts, "POST", "/bookmarks", `{"url":"a","tags":"nope"}`); c != 400 {
		t.Fatalf("bad tags: %d", c)
	}
	if c, _ := do(t, ts, "POST", "/bookmarks", `{"url":"a","tags":[1]}`); c != 400 {
		t.Fatalf("bad tags2: %d", c)
	}
	// create 1 (defaults)
	c, b := do(t, ts, "POST", "/bookmarks", `{"url":"http://a"}`)
	if c != 201 {
		t.Fatalf("create: %d %s", c, b)
	}
	var bm1 bookmarksapi.Bookmark
	json.Unmarshal([]byte(b), &bm1)
	if bm1.ID != "1" || bm1.Title != "" || !reflect.DeepEqual(bm1.Tags, []string{}) || bm1.Visits != 0 {
		t.Fatalf("bm1: %+v", bm1)
	}
	// create 2 with tags
	c, b = do(t, ts, "POST", "/bookmarks", `{"url":"http://b","title":"B","tags":["x","y"]}`)
	if c != 201 {
		t.Fatalf("create2: %d %s", c, b)
	}
	var bm2 bookmarksapi.Bookmark
	json.Unmarshal([]byte(b), &bm2)
	if bm2.ID != "2" {
		t.Fatalf("bm2 id: %+v", bm2)
	}
	// create 3
	c, b = do(t, ts, "POST", "/bookmarks", `{"url":"http://c"}`)
	if c != 201 {
		t.Fatalf("create3: %d %s", c, b)
	}

	// empty-store list check already passed; now list sorted
	c, b = do(t, ts, "GET", "/bookmarks", "")
	if c != 200 {
		t.Fatalf("list: %d", c)
	}
	var list []bookmarksapi.Bookmark
	json.Unmarshal([]byte(b), &list)
	if len(list) != 3 || list[0].ID != "1" || list[1].ID != "2" || list[2].ID != "3" {
		t.Fatalf("list order: %v", list)
	}

	// visit 3 twice, 2 once -> order 3,2,1
	if c, _ = do(t, ts, "POST", "/bookmarks/3/visit", ""); c != 200 {
		t.Fatalf("visit: %d", c)
	}
	if c, b = do(t, ts, "POST", "/bookmarks/3/visit", ""); c != 200 || !strings.Contains(b, `"visits":2`) {
		t.Fatalf("visit2: %d %s", c, b)
	}
	if c, _ = do(t, ts, "POST", "/bookmarks/2/visit", ""); c != 200 {
		t.Fatalf("visit2b: %d", c)
	}
	_, b = do(t, ts, "GET", "/bookmarks", "")
	json.Unmarshal([]byte(b), &list)
	if list[0].ID != "3" || list[1].ID != "2" || list[2].ID != "1" {
		t.Fatalf("sorted list: %v", list)
	}

	// get
	c, b = do(t, ts, "GET", "/bookmarks/2", "")
	if c != 200 || !strings.Contains(b, `"id":"2"`) {
		t.Fatalf("get: %d %s", c, b)
	}
	if c, _ = do(t, ts, "GET", "/bookmarks/99", ""); c != 404 {
		t.Fatalf("get 404: %d", c)
	}
	if c, _ = do(t, ts, "GET", "/bookmarks/abc", ""); c != 404 {
		t.Fatalf("get non-numeric: %d", c)
	}

	// patch
	c, b = do(t, ts, "PATCH", "/bookmarks/1", `{"title":"New"}`)
	if c != 200 || !strings.Contains(b, `"title":"New"`) || !strings.Contains(b, `"tags":[]`) {
		t.Fatalf("patch title: %d %s", c, b)
	}
	c, b = do(t, ts, "PATCH", "/bookmarks/1", `{"tags":["z"]}`)
	if c != 200 || !strings.Contains(b, `"tags":["z"]`) || !strings.Contains(b, `"title":"New"`) {
		t.Fatalf("patch tags: %d %s", c, b)
	}
	// visits unchanged by patch
	if !strings.Contains(b, `"visits":0`) {
		t.Fatalf("patch changed visits: %s", b)
	}
	// invalid patch body
	if c, _ = do(t, ts, "PATCH", "/bookmarks/1", `nope`); c != 400 {
		t.Fatalf("patch invalid: %d", c)
	}
	if c, _ = do(t, ts, "PATCH", "/bookmarks/1", `{"title":""}`); c != 400 {
		t.Fatalf("patch empty title: %d", c)
	}
	if c, _ = do(t, ts, "PATCH", "/bookmarks/1", `{"tags":5}`); c != 400 {
		t.Fatalf("patch bad tags: %d", c)
	}
	if c, _ = do(t, ts, "PATCH", "/bookmarks/99", `{"title":"x"}`); c != 404 {
		t.Fatalf("patch 404: %d", c)
	}

	// visit 404
	if c, _ = do(t, ts, "POST", "/bookmarks/99/visit", ""); c != 404 {
		t.Fatalf("visit 404: %d", c)
	}

	// delete
	if c, _ = do(t, ts, "DELETE", "/bookmarks/1", ""); c != 204 {
		t.Fatalf("delete: %d", c)
	}
	if c, _ = do(t, ts, "DELETE", "/bookmarks/1", ""); c != 404 {
		t.Fatalf("delete 404: %d", c)
	}
	_, b = do(t, ts, "GET", "/bookmarks", "")
	if !strings.Contains(b, `"id":"2"`) || strings.Contains(b, `"id":"1"`) {
		t.Fatalf("after delete: %s", b)
	}

	// unknown routes
	for _, tc := range [][2]string{{"GET", "/"}, {"PUT", "/bookmarks"}, {"POST", "/bookmarks/1/other"}, {"GET", "/bookmarks/1/visit"}, {"GET", "/nope"}} {
		if c, _ := do(t, ts, tc[0], tc[1], ""); c != 404 {
			t.Fatalf("404 fallback %s %s: %d", tc[0], tc[1], c)
		}
	}

	// empty store returns []
	for i := 2; i <= 3; i++ {
		do(t, ts, "DELETE", fmt.Sprintf("/bookmarks/%d", i), "")
	}
	c, b = do(t, ts, "GET", "/bookmarks", "")
	if c != 200 || strings.TrimSpace(b) != "[]" {
		t.Fatalf("empty list: %d %q", c, b)
	}
}

func TestConcurrentVisits(t *testing.T) {
	srv := bookmarksapi.NewServer()
	ts := httptest.NewServer(srv)
	defer ts.Close()
	do(t, ts, "POST", "/bookmarks", `{"url":"http://a"}`)
	var wg sync.WaitGroup
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			do(t, ts, "POST", "/bookmarks/1/visit", "")
		}()
	}
	wg.Wait()
	_, b := do(t, ts, "GET", "/bookmarks/1", "")
	if !strings.Contains(b, `"visits":200`) {
		t.Fatalf("lost updates: %s", b)
	}
}

var _ = bytes.NewReader // keep import if unused elsewhere
EOF
